import {foodCatalog} from './food-catalog.js';
import {koreanDiningPayload} from './korean-dining.js';
import {europeanCountries,popularDestinations} from './destinations.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={back:'M19 12H5M12 5l-7 7 7 7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',camera:'M4 6h4l2-3h4l2 3h4a2 2 0 0 1 2 2v11H2V8a2 2 0 0 1 2-2ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',receipt:'M5 2h14v20l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h5',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 3a4 4 0 0 1 0 8M19 14a4 4 0 0 1 3 4v3',user:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0M5 19c1-6 13-6 14 0',heart:'M20 4c5 5-2 11-8 16C6 15-1 9 4 4c3-3 6 0 8 2 2-2 5-5 8-2Z',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-1 5 6 6',sound:'m3 9 5 0 5-5v16l-5-5H3ZM17 8c3 2 3 6 0 8M20 5c5 4 5 10 0 14',expand:'M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v4M8 23h8',close:'m6 6 12 12M18 6 6 18',flash:'m13 2-8 12h7l-1 8 8-12h-7Z',image:'M3 3h18v18H3ZM3 17l5-6 5 5 3-3 5 5M17 7h.1',check:'m5 12 4 4L19 6',edit:'m4 16 12-12 4 4L8 20H4ZM14 6l4 4',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18M12 3c5 5 5 13 0 18',bag:'M4 7h16v15H4ZM8 7V5a4 4 0 0 1 8 0v2'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;
const btn=(text,action,cls='primary')=>`<button class="${cls}" ${action}>${text}</button>`;
const goAttr=p=>`data-go="${p}"`;
const top=(title,back='home',extra='')=>`<header class="topbar"><button class="icon-btn" data-go="${back}" aria-label="뒤로">${icon('back')}</button><strong>${title}</strong>${extra||'<span></span>'}</header>`;
const nav=active=>`<nav class="bottom-nav" aria-label="하단 메뉴">${[['home','home','홈'],['history','receipt','주문내역'],['friends','users','동반인'],['my','user','마이페이지']].map(([p,i,n])=>`<button data-go="${p}" class="${p===active?'active':''}" ${p===active?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav>`;
const wrap=(s,active)=>`<section class="screen ${active?'tab-screen':''} ${active==='home'?'home-screen':''}">${s}${active?nav(active):''}</section>`;
const money=v=>`€ ${Number(v).toFixed(2)}`;let rate=1550;const won=v=>`약 ${Math.round(v*rate).toLocaleString('ko-KR')}원`;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('hanip-v3-'+k))??f}catch{return f}};
const state={page:'home',city:read('city',{ko:'키우시',country:'이탈리아',code:'IT',latitude:43.0157,longitude:11.9489}),cart:read('cart',[]),friends:read('friends',['김미영']),ratings:read('ratings',{}),name:read('name','박성호'),avoid:read('avoid',['버섯','가지']),allergies:read('allergies',[]),prefs:read('prefs',['국물 요리','매콤한 맛']),request:'',photos:[],photoIndex:0,category:'zuppe',review:0,tip:false,tipPercent:5,extra:0,query:'',country:'',cityRows:[],searchToken:0,analysis:0,conversationPhase:0,selected:null,nearCategory:'전체',settings:read('settings',{}),connected:true};
function save(k,v){localStorage.setItem('hanip-v3-'+k,JSON.stringify(v))}let items=[],timers=[],toastTimer;const categoryNames={zuppe:'수프',secondi:'메인 요리',cocktails:'칵테일'};
const photo=i=>{const src=i.image?.url||'';return src.startsWith('http')?src:`assets/${i.id}.jpg`};
const foodName=i=>i.korean||i.original;const find=id=>items.find(i=>i.id===id);const sum=()=>state.cart.reduce((s,r)=>s+(find(r.id)?.price||0)*r.qty,0);const count=()=>state.cart.reduce((s,r)=>s+r.qty,0);const selected=(id,owner)=>state.cart.find(r=>r.id===id&&r.owner===owner)?.qty||0;
const warning=i=>[...new Set([...state.avoid,...state.allergies])].filter(a=>(i.ingredients?.join(' ')+i.description+foodName(i)+allergenText(i)).includes(a));
function clearTimers(){timers.forEach(clearTimeout);timers=[]}function later(fn,ms){timers.push(setTimeout(fn,ms))}
function go(page){clearTimers();state.page=page;$('#overlay').innerHTML='';render();if(page==='analysis'){state.analysis=0;render();[1100,2300,3500].forEach((t,i)=>later(()=>{state.analysis=i+1;render();if(i===2)later(()=>go('restaurant'),650)},t))}if(page==='menu'&&state.friends.length&&!state.companionDemo&&!state.cart.some(r=>r.owner!=='나')){state.companionDemo=true;later(()=>{add(items[2].id,state.friends[0],false);toast(`${state.friends[0]}님이 담았어요`,items[2]);render()},4200)}if(page==='conversation'){state.conversationPhase=0;render();conversationPrompt()}if(page==='destination')startSearch();location.hash=page}
function toast(text,item){clearTimeout(toastTimer);$('#toast').innerHTML=`${item?`<img src="${photo(item)}" alt="">`:icon('check')}<div><b>${esc(text)}</b>${item?`<small>${esc(foodName(item))}</small>`:''}</div>`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2000)}
function add(id,owner='나',show=true){let r=state.cart.find(r=>r.id===id&&r.owner===owner);if(r)r.qty++;else state.cart.push({id,owner,qty:1});save('cart',state.cart);if(show)toast('장바구니에 담았어요',find(id))}
function change(id,owner,delta){let r=state.cart.find(r=>r.id===id&&r.owner===owner);if(r)r.qty+=delta;state.cart=state.cart.filter(r=>r.qty>0);save('cart',state.cart);render()}
function foodCard(i){const mine=selected(i.id,'나'),theirs=state.cart.filter(r=>r.id===i.id&&r.owner!=='나');return `<article class="food-card" data-detail="${i.id}" role="button" tabindex="0" aria-label="${esc(foodName(i))} 상세 보기"><div class="food-photo"><img src="${photo(i)}" alt="${esc(foodName(i))}" loading="lazy">${mine||theirs.length?`<span class="selection">${mine?'나 '+mine+'개 ':''}${theirs.map(r=>esc(r.owner)+' '+r.qty+'개').join(' · ')}</span>`:''}<button class="add" data-add="${i.id}" aria-label="${esc(foodName(i))} 담기">${mine?'✓':'+'}</button></div><div class="food-copy"><span class="original">${esc(i.original)}</span><h3>${esc(foodName(i))}</h3><p>${esc(i.listDescription||i.description)}</p>${warning(i).length?`<span class="warning">${esc(warning(i).join(' · '))} 포함</span>`:''}<div class="price">${money(i.price)}</div><div class="won">${won(i.price)}</div></div></article>`}
function home(){return wrap(`<div class="home-content"><div class="between home-top"><button class="location-pill" data-go="destination">${icon('pin')}${esc(state.city.country)} · ${esc(state.city.ko)} <span class="location-caret" aria-hidden="true"></span></button><button class="sharing-avatars" data-go="friends" aria-label="${state.friends.length+1}명이 함께 공유 중 · 동반인 보기" title="${state.friends.length+1}명이 함께 공유 중"><span class="sharing-avatar sharing-self">나</span>${state.friends.slice(0,2).map(n=>`<span class="sharing-avatar">${esc(n.slice(0,1))}</span>`).join('')}${state.friends.length>2?`<span class="sharing-avatar sharing-more">+${state.friends.length-2}</span>`:''}</button></div><h1 class="home-heading">메뉴판을 찍으면 번역부터 주문까지</h1><button class="scan-cta" data-go="camera">${icon('camera')} 메뉴판 찍기</button><div class="two-col"><button class="quick-card" data-go="menu">${icon('receipt')}<b>방금 본 메뉴판</b><small>Osteria La Solita Zuppa</small></button><button class="quick-card" data-go="review">${icon('heart')}<span class="dot"></span><b>평가 안 한 메뉴</b><small>${Math.max(0,3-Object.keys(state.ratings).length)}개 남았어요</small></button></div><button class="home-link" data-go="nearby">${icon('pin')}<span><b>지금 내 주변 식당 찾기</b><small>현재 위치에서 맛있는 발견</small></span><span class="chevron">›</span></button><button class="home-link" data-go="asian">${icon('globe')}<span><b>아시안 미식 / 한식당 추천</b><small>익숙한 맛이 그리운 순간</small></span><span class="chevron">›</span></button><div class="ranking"><div class="between"><span class="section-label">한국인 입맛 랭킹</span><button class="small" data-go="ranking">전체 보기 ›</button></div><div class="rank-scroll">${ranked().slice(0,5).map((i,n)=>`<button class="rank-card" ${i.regional?`data-rank="${i.id}"`:`data-detail="${i.id}"`}>${i.regional?`<div class="rank-illustration">${i.emoji||'🍽'}</div>`:`<img src="${photo(i)}" alt="${esc(foodName(i))}">`}<div><b><em>${n+1}</em>${esc(foodName(i))}</b>${ratingLine(i)}${rankingQuote(i)}</div></button>`).join('')}</div></div></div>`,'home')}
function ratingData(i){
 const idx=items.findIndex(x=>x.id===i.id), samples=idx===2?[5,5,5,4,5]:idx===3?[5,4,5]:idx===7?[5,4,4,5]:[5,4,5];
 const own=state.ratings[i.id],values=own===undefined?samples:[...samples,[5,3,1][own]];
 const quotes={"ZUPPA DI PORRI E PATATE":"감자죽처럼 부드럽고 대파 향이 은은해요.","ZUPPA DI ZUCCA E FARRO":"달지 않은 호박죽에 밀알이 톡톡 씹혀요.","ZUPPA DI CECI E PORCINI":"버섯 향이 진하고 콩이 들어 든든해요.","CINGHIALE IN SALMI'":"장조림처럼 진한 풍미, 와인 향이 매력적이에요.","BACCALA' ALLA FIORENTINA":"바삭한 대구에 토마토 소스가 잘 어울려요."};
 return {score:(values.reduce((a,b)=>a+b,0)/values.length).toFixed(1),count:values.length,quote:own===undefined?(quotes[i.original]||i.listDescription||i.analogy||i.description||'익숙한 재료에 현지의 풍미가 더해져요.'):["또 먹고 싶어요.","한 번이면 충분해요.","제 입맛에는 조금 아쉬웠어요."][own],own:own!==undefined};
}
function ratingLine(i,detail=false){const r=ratingData(i);return `<div class="rating-line ${detail?'detail-rating-line':''}"><span class="rating-score"><span class="rating-star">★</span> ${r.score}</span><span class="rating-scale">/ 5</span><span class="rating-count">리뷰 ${r.count}개</span></div>`;}
function rankingQuote(i){const r=ratingData(i);return `<p class="ranking-quote">${esc(r.quote)}</p>${r.own?'<span class="my-review-label">내 평가 반영</span>':''}`;}
function ranked(){if(!/키우시|치우시/.test(state.city.ko)){let list=(foodCatalog[state.city.code]||foodCatalog.IT).filter(i=>!i.dessert);const seed=Array.from(state.city.name||state.city.ko).reduce((n,c)=>n+c.codePointAt(0),0)%list.length;return Array.from({length:Math.min(5,list.length)},(_,n)=>({...list[(seed+n)%list.length],id:'regional-'+n,regional:true}));}let base=state.city.code==='IT'?[items[2],items[3],items[7],items[4],items[0]]:[items[4],items[3],items[2],items[7],items[0]];return base.filter(Boolean).sort((a,b)=>Number(ratingData(b).score)-Number(ratingData(a).score))}
function camera(){return wrap(`<div class="camera-screen"><div class="topbar"><button class="icon-btn" data-go="home" aria-label="촬영 닫기">${icon('close')}</button><strong>${state.photos.length?'다음 장도 찍어주세요':'메뉴판을 찍어주세요'}</strong><button class="icon-btn" data-action="flash" aria-label="플래시">${icon('flash')}</button></div><div class="viewfinder"><div class="corner"></div><div class="menu-paper"><div class="paper-brand">Osteria</div><h2>La Solita Zuppa</h2><h4>— ZUPPE —</h4>${items.slice(0,4).map(i=>`<div class="paper-line"><span>${esc(i.original.toLowerCase().replace('zuppa','Zuppa'))}</span><b>${i.price}</b></div>`).join('')}<h4>— SECONDI —</h4>${[items[11],items[7]].map(i=>`<div class="paper-line"><span>${esc(i.original.split(' ').slice(0,3).join(' '))}</span><b>${i.price}</b></div>`).join('')}<small>Coperto € 2,50</small></div></div><div class="camera-tools"><div class="camera-hint">${state.photos.length?`${state.photos.length}장 찍었어요 · 더 있으면 계속 찍어주세요`:'메뉴판이 네모 칸에 꽉 차게 맞춰주세요'}</div>${!state.photos.length?'<small>여러 장이면 한 장씩 차례로 찍어주세요</small>':''}<div class="shutter-row"><button class="icon-btn" data-action="album" aria-label="앨범에서 선택">${icon('image')}</button><button class="shutter" data-action="capture" aria-label="메뉴판 촬영"></button>${state.photos.length?`<button class="thumb-stack" data-go="photos" aria-label="촬영 사진 ${state.photos.length}장 보기">La Solita Zuppa<br>— MENU —<br>••••••••••<br>••••••••••<b>${state.photos.length}</b></button>`:'<div style="width:43px"></div>'}</div>${state.photos.length?btn(`메뉴판 ${state.photos.length}장 해석하기`,goAttr('analysis')):'<div style="height:56px"></div>'}</div></div>`)}
function photos(){return wrap(`${top('촬영한 메뉴판','camera')}<div class="scroll"><div class="between" style="margin-bottom:17px"><h2>총 ${state.photos.length}장</h2><button class="pill" data-go="camera">+ 더 찍기</button></div><div class="photo-grid">${state.photos.map((p,n)=>`<div class="photo-preview"><button data-delete-photo="${n}" aria-label="${n+1}번째 사진 삭제">×</button><div data-enlarge-photo="${n}" style="height:100%;cursor:zoom-in">${p?`<img src="${p}" alt="촬영 사진 ${n+1}">`:`<div style="background:#fcf7ed;padding:35px 12px;font-size:11px;height:100%"><b>Osteria<br>La Solita Zuppa</b><br><br>— ZUPPE —<br><br>Zuppa di ceci e porcini<br>Zuppa di melanzane fumé<br>Zuppa di porri e patate<br>Zuppa di zucca e farro<br><br>— SECONDI —</div>`}</div></div>`).join('')}</div>${!state.photos.length?'<div class="empty">촬영한 사진이 없어요.</div>':''}</div><div class="fixed-bottom">${btn('메뉴판 해석하기',`${goAttr('analysis')} ${!state.photos.length?'disabled':''}`)}</div>`)}
function analysis(){return wrap(`<div class="analysis"><h2>메뉴판을<br>한국인 입맛으로<br>풀어드리는 중이에요</h2><div class="card">${[['메뉴 이름 읽기','22개 메뉴를 찾았어요'],['가격과 재료 확인하기',`${Math.max(state.photos.length,1)}장 중 ${Math.min(state.analysis+1,Math.max(state.photos.length,1))}장째`],['한국 음식에 빗대어 설명하기','익숙한 맛으로 설명을 정리해요']].map(([t,s],n)=>`<div class="progress-row ${state.analysis>n?'done':state.analysis===n?'busy':'wait'}"><span class="progress-circle">${state.analysis>n?'✓':''}</span><div><b>${t}</b>${state.analysis>=n?`<small>${s}</small>`:''}</div></div>`).join('')}</div><p class="subtle-note" style="text-align:center;margin-top:20px">낯선 이름 속에 숨어 있는 익숙한 맛을 찾고 있어요.</p></div>`)}
function mapBase(mode){
 const isMain=mode==='restaurant',asian=mode==='asian';
 const names=asian?['Seoul Garden','Ristorante Sakura','Il Gusto d’Oriente','Asian Wok']:['Osteria Etrusca','Il Grillo è Buoncantore','Trattoria della Zuppa'];
 return wrap(`<div class="map-screen ${isMain?'restaurant-confirm-screen':''}"><div class="map"><div class="map-fallback"></div><iframe title="키우시 주변 지도" src="https://www.openstreetmap.org/export/embed.html?bbox=11.9428%2C43.0132%2C11.9508%2C43.0187&layer=mapnik&marker=43.0159475%2C11.9468233" loading="lazy"></iframe></div><button class="pin" data-action="map-select" aria-label="지도에서 식당 선택"><span>1</span></button>${top('',isMain?'camera':'home')}<div class="map-sheet"><button class="handle" data-action="sheet" aria-label="식당 패널 펼치기"></button><div class="sheet-scroll"><span class="restaurant-region">${isMain?'이탈리아 · 토스카나':esc(state.city.country)+' · '+esc(state.city.ko)}</span><h2 class="restaurant-sheet-title">${isMain?'Osteria La Solita Zuppa':asian?'익숙한 맛, 가까운 곳에서':'지금, 어떤 맛이 당기세요?'}</h2><p class="restaurant-question">${isMain?'이곳이 맞나요?':'카테고리를 고르면 지도와 목록에서 확인할 수 있어요.'}</p>${!isMain?`<div class="tabs" style="margin-top:14px">${(asian?['전체','한식당','아시안']:['전체','국물 요리','고기 요리','해산물','가벼운 한 끼']).map(c=>`<button class="${state.nearCategory===c?'active':''}" data-near-category="${c}">${c}</button>`).join('')}</div>`:''}${isMain?`<img class="restaurant-hero" src="assets/restaurant-google.jpg" alt="Osteria La Solita Zuppa의 실제 실내 · 구글맵 소유자 제공 사진"><div class="between restaurant-type-row"><span>토스카나 요리 · 오스테리아</span><button class="pill active" data-go="menu">선택</button></div><div class="divider"></div><div class="between"><h3>근처의 다른 식당</h3><span class="small">3곳</span></div>`:''}${names.filter((n,i)=>!asian||state.nearCategory==='전체'||(state.nearCategory==='한식당'?i===0:i>0)).map((n,i)=>`<div class="restaurant-row"><img src="${photo(items[i+2])}" alt="식당 예시 사진"><div><h3>${n}</h3><small>${asian?(i===0?'한식 · 찌개 · 구이':'아시안 · 현지 식당'):state.nearCategory==='전체'?'토스카나 요리 · 현지 식당':esc(state.nearCategory)}${isMain?'':`<br>도보 ${4+i*3}분 · ${esc(state.city.ko)}`}</small></div><button class="pill" data-restaurant="${esc(n)}">선택</button></div>`).join('')}${isMain?'':'<p class="subtle-note">디자인 시연용 식당 목록이에요. 실제 위치 검색은 연결하지 않았어요.</p>'}</div></div></div>`)
}
function menu(){return wrap(`${top('메뉴를 골라주세요','restaurant')}<div class="menu-header"><div class="between"><div class="row"><div class="avatars"><span class="avatar">나</span>${state.friends.length?`<span class="avatar">${state.friends[0][0]}</span>`:''}</div><b class="small" style="color:#636977">${state.friends.length?esc(state.friends[0])+'님과 함께 고르는 중':'나만의 메뉴를 고르는 중'}</b></div><button class="small blue" data-action="invite">초대</button></div><div class="tabs menu-category-tabs" role="tablist" aria-label="메뉴 카테고리">${['zuppe','secondi','cocktails'].map(c=>`<button class="${state.category===c?'active':''}" data-category="${c}" role="tab" aria-selected="${state.category===c}">${categoryNames[c]}<span>${items.filter(i=>i.category===c).length}</span></button>`).join('')}</div></div><div class="scroll" style="padding-top:0"><div class="food-grid">${items.filter(i=>i.category===state.category).map(foodCard).join('')}</div><p class="subtle-note">공식 웹메뉴 보관 자료 · 2026.10.10<br>원화는 시연 환율 €1 = ${rate.toLocaleString()}원 기준이에요.</p></div><div class="fixed-bottom">${btn(`${icon('bag')} <span>${count()}개</span><span style="margin-left:auto">장바구니 가기</span>`,goAttr('cart'))}</div>`)}
function detail(){let i=find(state.selected)||items[3];return wrap(`<div class="detail-scroll"><div class="detail-hero"><img src="${photo(i)}" alt="${esc(foodName(i))}"><button class="icon-btn" data-go="menu" aria-label="메뉴 목록으로">${icon('back')}</button><span class="photo-caption">식당 웹메뉴에 등록된 사진</span></div><div class="detail-body"><span class="original">${esc(i.original)}</span><h2>${esc(foodName(i))}</h2><div class="detail-price">EUR <b>${i.price.toFixed(2)}</b><small>${won(i.price)}</small></div><div class="detail-rating-block">${ratingLine(i,true)}${rankingQuote(i)}<span class="demo-label">프로토타입 시연 리뷰</span></div>${warning(i).length?`<div class="warning" style="font-size:12px;padding:8px 11px">${esc(warning(i).join(' · '))}가 포함되어 있어요 · 내 입맛 설정</div>`:''}<div class="ai-box"><span class="label">✦ 한국 음식으로 치면</span><p style="font-size:11px;margin-top:3px">AI가 한국 음식에 빗대어 설명했어요</p><h3>${esc(analogyHeadline(i))}</h3><p>${esc(i.analogy||cocktailAnalogy(i))}</p></div><div class="info-card"><div class="row">${icon('check')}<div><h3>메뉴판에 적힌 정보</h3><small>식당 공식 웹메뉴에서 확인했어요</small></div></div><div class="divider"></div><small>식당의 음식 설명</small><p>${esc(i.description||'식당이 등록한 상세 설명은 없어요.')}</p><div class="divider"></div><small>확인된 재료</small><p>${esc(i.ingredients?.join(' · ')||'웹메뉴에 재료가 따로 표시되지 않았어요.')}</p><div class="divider"></div><small>알레르기 표시</small><p>${esc(allergenText(i))}</p><details style="font-size:11px;color:#9a9eaa;margin-top:14px"><summary>원문과 출처 보기</summary><p>${esc(i.officialDescription||'상세 설명 없음')}</p><a href="${esc(i.sources?.[0]?.url||i.source||'https://11729.ordinaincloud.it/menu/13361/products')}" target="_blank" rel="noopener">식당 공식 웹메뉴 ↗</a></details></div><div class="ai-box"><span class="label">✦ AI가 보충한 음식 이야기</span><p style="font-size:11px;margin:3px 0 15px">일반적인 음식 특성이에요. 이 식당의 조리법과 다를 수 있어요.</p><div class="divider"></div><span class="blue small">추가로 쓰일 수 있는 재료</span><div class="tags">${(i.category==='zuppe'?['육수','양파']:i.category==='cocktails'?['얼음','과일 껍질']:['육수','조리용 기름']).map(t=>`<span>${t}</span>`).join('')}</div><p style="font-size:11px;margin-top:8px">일반적인 조리에서 쓰이는 예시예요. 이 식당에서 사용하는지는 확인이 필요해요.</p><div class="divider"></div><span class="blue small">맛과 식감</span><p>${esc(generalInfo(i))}</p><div class="divider"></div><span class="blue small">조리법과 문화</span><p>${esc(i.cooking||'이탈리아에서는 식사 전 가볍게 즐기는 아페리티보로 칵테일을 마시곤 해요. 재료의 배합과 도수는 식당마다 달라요.')}</p><div class="divider"></div><span class="blue small">알레르기 가능성과 확인할 정보</span><p>${i.ingredients?.some(t=>/치즈|파르메산/.test(t))?'치즈가 포함되어 유제품에 민감하다면 확인이 필요해요. ':''}육수와 추가 재료, 조리 과정의 교차 접촉은 직원에게 확인해주세요.</p>${btn('직원에게 확인하는 문장 보기','data-action="allergen-phrase"','secondary')}</div><p class="subtle-note" style="text-align:center">한국 음식과의 비교는 이해를 돕는 표현이에요.</p></div></div><div class="fixed-bottom">${btn(`${selected(i.id,'나')?'하나 더 담기':'장바구니에 담기'}`,`data-add="${i.id}"`)}</div>`)}
function analogyHeadline(i){const k=items.indexOf(i);return ['콩죽에 버섯 향을 더한 느낌이에요','구운 가지나물을 수프로 즐기는 느낌이에요','대파의 단맛을 더한 부드러운 감자죽 같아요','밀알을 넣은 고소한 호박죽에 가까워요'][k]||({'cocktails':'과일 향과 쌉싸름함을 즐기는 식전주예요'}[i.category])||foodName(i)}
function cocktailAnalogy(i){return i.original==='AMERICANO'?'커피가 아니라 칵테일이에요. 탄산이 있는 쌉싸름한 식전주로 떠올려보세요.':i.original.includes('SPRITZ')?'과일 향 탄산주처럼 가볍게 마시는 스타일이지만, 쌉싸름한 맛이 함께 느껴질 수 있어요.':'달콤하고 쌉싸름한 향을 즐기는 이탈리아 식전주예요. 실제 도수와 배합은 직원에게 확인해주세요.'}
function allergenText(i){let m=i.officialDescription?.match(/Allergeni[:.]?\s*([^V\n]+)/i)||i.officialDescription?.match(/ALLEREGENI[.:]?\s*(.*)/i);const names={1:'글루텐 함유 곡물',2:'갑각류',3:'달걀',4:'생선',5:'땅콩',6:'대두',7:'우유·유제품',8:'견과류',9:'셀러리',10:'겨자',11:'참깨',12:'아황산염',13:'루핀',14:'연체동물'};return m?[...new Set((m[1].match(/\d+/g)||[]).map(n=>names[n]?names[n]+' (EU '+n+')':n))].join(' · ')||'자세한 알레르기 정보는 직원에게 확인해주세요.':'상세 알레르기 정보는 직원에게 확인해주세요.'}
function generalInfo(i){if(i.category==='cocktails')return cocktailAnalogy(i);if(i.original.includes('PORCINI'))return '포르치니는 향이 진한 버섯이에요. 구수한 국물과 숲 향을 떠올리면 이해하기 쉬워요.';if(i.original.includes('MELANZANE'))return '부드러운 가지에 장작의 훈연 향, 치즈의 짭짤하고 고소한 풍미가 어우러질 수 있어요.';if(i.original.includes('FARRO'))return '호박의 은은한 단맛과 파로 밀알의 톡톡 씹히는 식감이 대비되는 수프예요.';if(i.original.includes('PATATE')&&i.category==='zuppe')return '서양 대파를 익히면 매운맛이 줄고 단맛이 살아나요. 감자 덕분에 부드럽고 포근한 식감을 기대할 수 있어요.';return i.analogy||'한국 음식과는 양념이 다르지만, 주재료와 조리법을 기준으로 맛을 떠올려보세요. 실제 간과 식감은 식당의 조리에 따라 달라요.'}
function cart(){let owners=[...new Set(state.cart.map(r=>r.owner))].sort((a,b)=>a==='나'?-1:b==='나'?1:0);return wrap(`${top('함께 담은 장바구니','menu')}<div class="scroll">${!state.cart.length?`<div class="empty">${icon('bag')}<h3>아직 담은 메뉴가 없어요</h3><p>마음에 드는 메뉴를 골라보세요.</p><br>${btn('메뉴 둘러보기',goAttr('menu'),'secondary')}</div>`:owners.map(owner=>`<div class="cart-group"><div class="cart-title">${owner==='나'?'내 메뉴':esc(owner)+'님 메뉴'} <span class="muted small">· ${state.cart.filter(r=>r.owner===owner).reduce((s,r)=>s+r.qty,0)}개</span></div>${state.cart.filter(r=>r.owner===owner).map(r=>{let i=find(r.id);return `<div class="cart-item"><img src="${photo(i)}" alt="${esc(foodName(i))}"><div class="copy"><span class="original">${esc(i.original)}</span><h3>${esc(foodName(i))}</h3><div class="between"><span class="price">${money(i.price)}</span><button class="small" data-remove="${r.id}" data-owner="${esc(owner)}">삭제</button></div><div class="won">${won(i.price)}</div><div class="stepper"><button data-qty="${r.id}" data-owner="${esc(owner)}" data-delta="-1" aria-label="수량 줄이기">−</button><span>${r.qty}</span><button data-qty="${r.id}" data-owner="${esc(owner)}" data-delta="1" aria-label="수량 늘리기">+</button></div></div></div>`}).join('')}<div class="total-line"><span>${owner==='나'?'내':esc(owner)+'님'} 합계</span><b>${money(state.cart.filter(r=>r.owner===owner).reduce((s,r)=>s+find(r.id).price*r.qty,0))}</b></div></div>`).join('')}</div><div class="fixed-bottom"><label class="tip-check"><input type="checkbox" id="tip" ${state.tip?'checked':''}>선택 팁 포함 <select id="tip-percent" style="border:0;background:none;color:#6d7892"><option value="5" ${state.tipPercent===5?'selected':''}>5%</option><option value="10" ${state.tipPercent===10?'selected':''}>10%</option></select></label><div class="small" style="font-size:10px;margin:3px 0 10px">이탈리아에서 팁은 선택이에요. 서비스료 포함 여부를 확인하세요.</div><div class="summary-row"><span>음식 ${money(sum())}</span><span>${state.tip?'선택 팁 '+money(sum()*state.tipPercent/100):'팁 미포함'}</span></div><div class="summary-total"><div><b>예상 총액</b><small style="display:block">총 ${count()}개 · ${won(total())}</small></div><strong>${money(total())}</strong></div>${btn('주문 문장 만들기',`${goAttr('order')} ${!state.cart.length?'disabled':''}`)}</div>`)}
const total=()=>sum()*(1+(state.tip?state.tipPercent/100:0));
function orderSentences(){let lines=state.cart.map(r=>({i:find(r.id),qty:r.qty}));if(!lines.length)lines=[{i:items[2],qty:1},{i:items[3],qty:1}];let ko=lines.map(r=>`${foodName(r.i)} ${r.qty}개`).join(', ')+' 주세요.';let it='Vorremmo ordinare '+lines.map(r=>`${r.qty===1?'una porzione di':r.qty+' porzioni di'} ${r.i.original.toLowerCase()}`).join(' e ')+', per favore.';let request=requestTranslation(state.request);return{ko:ko+(state.request?' '+state.request:''),it:it+(request?' '+request:'')}}
function requestTranslation(text){if(!text.trim())return'';if(text.includes('훈제')&&text.includes('가지')&&text.includes('치즈'))return 'La zuppa di melanzane affumicate senza formaggio, per favore.';let parts=[];const ingredients=[['치즈','formaggio'],['고수','coriandolo'],['버섯','funghi'],['가지','melanzane'],['소금','sale'],['양파','cipolla'],['땅콩','arachidi'],['새우','gamberi']];for(const [ko,it]of ingredients)if(text.includes(ko))parts.push(`${/추가|더|넣어/.test(text)?'Con un po’ di '+it+' in più':'Senza '+it}, per favore.`);if(/맵지|안 맵|덜 맵/.test(text))parts.push('Non piccante, per favore.');if(/물/.test(text))parts.push('Potremmo avere anche dell’acqua, per favore?');if(/따로/.test(text))parts.push('A parte, per favore.');return parts.join(' ')}
function order(){let s=orderSentences();return wrap(`${top('주문하기','cart')}<div class="scroll"><div class="card order-card"><h2 id="order-ko">${esc(s.ko)}</h2><div class="divider"></div><div class="between"><small>이탈리아어</small><button class="icon-btn" data-action="speak-order" aria-label="주문 문장 듣기">${icon('sound')}</button></div><p class="italian" id="order-it">${esc(s.it)}</p><div class="right"><button class="icon-btn" data-go="enlarged" aria-label="주문 문장 확대">${icon('expand')}</button></div></div><label class="field-label" for="request">요청사항</label><textarea class="request" id="request" placeholder="입력하면 주문 문장에 바로 반영돼요.&#10;예: 치즈는 빼주세요">${esc(state.request)}</textarea><p class="subtle-note" id="request-status">치즈·고수·버섯 제외, 재료 추가, 맵기·물 요청을 시연할 수 있어요.</p></div><div class="fixed-bottom" style="background:transparent;box-shadow:none">${btn('실시간 대화하기',goAttr('conversation'))}<button class="text-link" data-action="finish-order">주문했어요 · 영수증 보기</button></div>`)}
function enlarged(){return wrap(`${top('직원에게 보여주세요','order',`<button class="icon-btn" data-action="speak-order" aria-label="음성 재생">${icon('sound')}</button>`)}<div class="fullscreen-text">${esc(orderSentences().it)}</div>`)}
function conversationPrompt(){modal(`<div class="preview"><small>주문 문장</small><p>${esc(orderSentences().ko)}</p><p>${esc(orderSentences().it)}</p></div><h2>아까 만든 주문 문장을<br>먼저 보여줄까요?</h2><div class="actions">${btn('네, 보여줄게요','data-action="show-order"')}${btn('아니요, 바로 말하기','data-action="skip-order"','secondary')}</div>`)}
function conversation(){let phase=state.conversationPhase;return wrap(`<div class="conversation"><div class="conversation-half staff ${phase===2?'speaking':''}"><div class="caption">ITALIANO · STAFF<button class="icon-btn" data-action="speak-staff" aria-label="이탈리아어 듣기">${icon('sound')}</button></div><div>${phase===1?`<div class="speech-current other initial-order">${esc(orderSentences().it)}</div>`:phase===2?'<div class="speech-history other">La zuppa di melanzane affumicate senza formaggio, per favore.</div><div class="speech-current self">Certamente,<br>va bene.</div>':'<div class="speech-current other muted">Possiamo iniziare<br>a parlare.</div>'}</div><div class="mic-row"><button class="mic-button" data-action="staff-speak">${icon('mic')} Parla</button>${phase===2?'<span>Sto parlando…</span>':''}</div></div><button class="conversation-end" data-action="finish-order">× &nbsp;대화 마치기</button><div class="conversation-half ${phase===3?'speaking':''}"><div class="caption">한국어 · 나<button class="icon-btn" data-action="speak-korean" aria-label="한국어 듣기">${icon('sound')}</button></div><div>${phase>=2?'<div class="speech-history self">훈제 가지 수프에 치즈는 빼주세요.</div><div class="speech-current other">네, 알겠습니다.</div>':`<div class="speech-current muted" style="font-size:20px">${phase===1?'직원에게 주문 문장을<br>보여주고 있어요.':'편하게 말해주세요.'}</div>`}</div><div class="between"><div class="mic-row"><button class="mic-button" data-action="my-speak">${icon('mic')} 말하기</button><span>${phase===3?'듣고 있어요…':'한국어로 말해주세요'}</span></div><div class="wave">${'<i></i>'.repeat(7)}</div></div></div></div>`)}
function receipt(){let rows=state.lastOrder?.cart||state.cart;let subtotal=rows.reduce((s,r)=>s+find(r.id).price*r.qty,0);return wrap(`${top('영수증 미리보기','history')}<div class="scroll"><span class="small">주문 완료</span><h2 style="margin-top:10px;font-size:24px">계산서에 붙을 금액과<br>현지 식사 문화를 한눈에</h2><div class="receipt"><h3>Osteria La Solita Zuppa</h3><p class="small" style="margin-top:5px">이탈리아 · 키우시 · 2026. 10. 26. · ${state.friends.length+1}명</p><div class="divider"></div>${rows.length?rows.map(r=>{let i=find(r.id);return `<div class="receipt-item"><div><b>${esc(foodName(i))} × ${r.qty}</b><span class="original">${esc(i.original)}</span></div><b style="white-space:nowrap">${money(i.price*r.qty)}</b></div>`}).join(''):'<p class="small">아직 주문한 메뉴가 없어요.</p>'}<div class="divider"></div><span class="small">이탈리아 · 현지 식당 안내</span><h3 style="margin:7px 0 13px">키우시에서 식사할 때</h3>${[['코페르토 · Coperto','자리·식기 준비 비용을 1인당 받는 식당이 있어요. 팁과는 달라요. 메뉴판과 직원에게 적용 금액을 확인해주세요.'],['물과 빵','생수나 빵은 별도 요금일 수 있어요. 주문 전 추가 금액을 확인해주세요.'],['팁은 선택이에요','팁은 의무가 아니에요. 서비스료가 이미 포함됐는지 먼저 확인하세요.']].map(([t,p])=>`<div class="receipt-info"><b>${t}</b><p>${p}</p></div>`).join('')}<a class="small" style="display:block;margin-top:13px" href="https://www.italia.it/en/italy/practical-information" target="_blank" rel="noopener">이탈리아 공식 관광 안내 ↗</a><p class="subtle-note">지역의 일반적인 관행이에요. 이 식당에 적용되는 요금은 메뉴판·직원에게 확인해주세요.</p><div class="divider"></div><label class="field-label" for="extra">확인한 추가 요금 합계 (EUR)</label><p class="subtle-note">물·빵·자리 비용 등 확인한 금액만 입력해요. 선택 팁도 포함할 수 있어요.</p><input class="input" id="extra" type="number" min="0" max="10000" step="0.5" value="${state.extra||''}" placeholder="미확인 · 합계에 포함하지 않음"><div class="divider"></div><div class="summary-row"><span>음식 ${money(subtotal)}</span><span>추가 요금 <span id="extra-amount">${money(state.extra)}</span></span></div><div class="between"><b>확인된 예상 합계</b><b id="receipt-total">${money(subtotal+state.extra)}</b></div><small id="receipt-won">${won(subtotal+state.extra)}</small><p class="subtle-note">식당이 발행한 영수증이 아닌 주문 요약이에요. 입력하지 않은 추가 요금은 제외돼 실제 계산서와 다를 수 있어요.</p></div>${btn('홈으로 가기',goAttr('home'))}<div style="height:9px"></div>${btn('추가 주문하기',goAttr('menu'),'secondary')}</div>`)}
function historyPage(){return wrap(`${top('주문내역')}<div class="scroll"><div class="card between"><div><h3>오늘의 한 끼는 어땠나요?</h3><small>평가가 남은 메뉴 ${Math.max(0,3-Object.keys(state.ratings).length)}개</small></div><button class="pill active" data-go="review">평가하기</button></div><p class="history-date">2026.10.26 월요일</p><div class="history-card"><div class="history-thumbs">${[items[2],items[3]].map(i=>`<img src="${photo(i)}" alt="${esc(foodName(i))}">`).join('')}<span>+1</span></div><h3>Osteria La Solita Zuppa</h3><p class="small">키우시 · 김미영님과 2명 · 수프 2, 메인 1</p><div class="between" style="margin-top:20px"><span class="small">예상 합계</span><b style="font-size:18px">${money(state.lastOrder?state.lastOrder.total:36)}</b></div><div class="history-actions"><button data-go="order">주문 문장</button><button data-go="receipt">영수증</button></div></div><p class="history-date">2026.10.24 토요일</p><button class="history-card row" style="width:100%;text-align:left" data-action="old-order"><img src="${photo(items[7])}" style="width:48px;height:48px;object-fit:cover;border-radius:15px" alt="지난 식사"><span><b>Trattoria Da Rosa</b><small style="display:block">피렌체 · 2명 · EUR 38.50</small></span><span style="margin-left:auto">›</span></button></div>`,'history')}
function review(){let list=[items[2],items[3],items[7]],i=list[state.review];if(!i)return wrap(`${top('오늘의 맛 기록','history')}<div class="scroll rating-saved">${icon('heart')}<h2>오늘의 맛을 기억했어요</h2><p class="muted">평가가 내 취향과<br>한국인 입맛 랭킹에 반영됐어요.</p><br>${btn('내 취향 추천 보기',goAttr('ranking'))}</div>`);return wrap(`${top('오늘의 맛 기록','history')}<div class="scroll"><div class="review-progress">${list.map((_,n)=>`<span class="${n<=state.review?'active':''}"></span>`).join('')}</div><h2 style="font-size:21px;font-weight:500">${esc(foodName(i))},<br>입맛에 맞으셨어요?</h2><img class="review-image" src="${photo(i)}" alt="${esc(foodName(i))}">${[['heart','또 먹고 싶어요','한국인 평점에 반영돼요'],['user','한 번이면 충분해요',''],['close','입맛에 안 맞아요','']].map(([ic,t,s],n)=>`<button class="review-option ${state.ratings[i.id]===n?'selected':''}" data-rating="${n}" data-item="${i.id}">${icon(ic)}<span>${t}${s?`<small>${s}</small>`:''}</span></button>`).join('')}</div>`)}
function friends(){return wrap(`${top('동반인')}<div class="scroll"><span class="eyebrow">TRAVEL TOGETHER</span><div class="between" style="margin:7px 0 19px"><h2 style="font-size:21px">이번 여행 동반인 <span class="small">${state.friends.length}</span></h2><button class="pill white" data-action="invite">${icon('users')} 초대</button></div>${state.friends.length?state.friends.map(n=>`<div class="card row" style="padding:19px 15px;margin-bottom:12px"><span class="avatar" style="width:42px;height:42px">${n.slice(-2)}</span><button data-edit-friend="${n}" style="text-align:left"><b>${n}</b><small style="display:block">${friendDescription(n)}</small></button><button class="pill" style="margin-left:auto;background:#fff;border:1px solid #e5e8ef" data-friend-remove="${n}">빼기</button></div>`).join(''):'<div class="card muted">동반인을 초대해 함께 메뉴를 골라보세요.</div>'}<div class="between" style="margin:25px 0 7px"><h3>친구 목록</h3><button class="small" data-action="new-friend">+ 새 친구</button></div>${['김미영','박정숙','김영수',...state.friends.filter(n=>!['김미영','박정숙','김영수'].includes(n))].map(n=>`<div class="friend-row"><span class="avatar">${n.slice(-2)}</span><button data-edit-friend="${n}" style="text-align:left;padding:0"><h3>${esc(n)}</h3><small>${friendDescription(n)}</small></button>${state.friends.includes(n)?'<span class="small" style="margin-left:auto;font-size:10px">함께하는 중</span>':`<button class="pill" data-friend-add="${esc(n)}">추가</button>`}</div>`).join('')}<p class="subtle-note" style="text-align:center;margin-top:26px">이름을 누르면 동반인 정보를 수정할 수 있어요.<br>연결된 동반인은 같은 메뉴판과 장바구니를 함께 봐요.</p></div>`,'friends')}
const friendDescription=n=>state.friendNotes?.[n]||({'김미영':'새우 알레르기 · 토마토 못 먹어요','박정숙':'갑각류 알레르기 · 고수 못 먹어요','김영수':'견과류 알레르기 · 양고기 못 먹어요'}[n]||'알레르기·못 먹는 음식 미등록');
function my(){return wrap(`${top('마이페이지')}<div class="scroll stack"><div class="card"><div class="row"><span class="avatar" style="width:51px;height:51px;font-size:21px;background:#e5e9f7">${esc(state.name.slice(-1))}</span><div><h3 style="font-size:20px">${esc(state.name)}님</h3><small>${esc(state.city.country)} · ${esc(state.city.ko)} 여행 중<br>카카오 계정으로 로그인 중</small></div><button class="icon-btn" style="margin-left:auto;background:#f2f2f5" data-action="edit-profile" aria-label="프로필 수정">${icon('edit')}</button></div><div class="profile-stat"><button data-go="history"><strong>${state.lastOrder?13:12}</strong><small>주문 기록</small></button><button data-go="review"><strong>${18+Object.keys(state.ratings).length}</strong><small>평가한 메뉴</small></button><button data-go="friends"><strong>${state.friends.length}명</strong><small>동반인</small></button></div></div><div class="card"><div class="between"><h3>내 입맛</h3><button class="small blue" data-action="taste">수정</button></div><div class="tags">${(state.allergies.length?state.allergies.map(a=>a+' 알레르기'):['알레르기 없음']).concat(state.avoid.map(a=>a+' 못 먹어요')).map(t=>`<span style="background:#f2f2f5;color:#80848f">${esc(t)}</span>`).join('')}${state.prefs.map(p=>`<span style="background:#eaf0ff;color:#5e75cc">${esc(p)} 좋아해요</span>`).join('')}</div></div><div class="card" style="padding:2px 20px"><button class="settings-row" data-go="friends"><span>${icon('users')} &nbsp; 함께 여행하는 사람</span><span>›</span></button><button class="settings-row" data-go="settings"><span>${icon('shield')} &nbsp; 개인정보와 설정</span><span>›</span></button><button class="settings-row" data-go="destination" style="border:0"><span>${icon('pin')} &nbsp; 여행 국가·도시 변경</span><span>›</span></button></div></div>`,'my')}
function settings(){return wrap(`${top('설정','my')}<div class="scroll"><div class="card"><h3>기본 설정</h3><button class="settings-row" data-action="edit-profile">사용자 정보 관리 <span>›</span></button><label class="settings-row">사용 언어<select id="language" style="border:0;background:none;color:#8e96a7"><option>한국어</option><option>English</option><option>Italiano</option></select></label><button class="settings-row" data-go="destination">여행 국가 및 지역 <span class="small">${esc(state.city.country)} · ${esc(state.city.ko)} ›</span></button></div><div class="card" style="margin-top:12px"><h3>사용 환경</h3><label class="settings-row">글자 크기<select id="font-size" style="border:0;background:none"><option value="normal">기본</option><option value="large" ${state.settings.font==='large'?'selected':''}>크게</option></select></label>${['알림 받기','카메라 접근','마이크 접근','위치 접근'].map(t=>`<label class="settings-row">${t}<input class="toggle" type="checkbox" data-setting="${t}" ${state.settings[t]!==false?'checked':''}></label>`).join('')}<p class="subtle-note">프로토타입의 설정 상태예요. 실제 기기 권한은 변경하지 않아요.</p></div><div class="card" style="margin-top:12px"><h3>서비스 관리</h3>${['사용 안내','개인정보 및 저장','서비스 정보'].map(t=>`<button class="settings-row" data-help="${t}">${t}<span>›</span></button>`).join('')}</div></div>`)}
function countryFlag(code){return /^[A-Z]{2}$/.test(code||'')?String.fromCodePoint(...code.split('').map(c=>127397+c.charCodeAt(0))):'🌍'}
function destination(){return wrap(`${top('여행지 설정')}<div class="scroll destination-content"><h2 class="destination-title">어디로 여행 가시나요?</h2><label class="searchbox destination-search">${icon('search')}<input id="city-query" value="${esc(state.query)}" placeholder="국가 또는 도시 검색" autocomplete="off" aria-label="국가 또는 도시 검색">${state.query?'<button data-action="clear-search" aria-label="검색 지우기">×</button>':''}</label><h3 class="current-destination-label">현재 여행지</h3><button class="current-destination" data-go="home" aria-label="현재 여행지 ${esc(state.city.country)} ${esc(state.city.ko)}"><span class="country-flag" aria-hidden="true">${countryFlag(state.city.code)}</span><span class="destination-copy"><b>${esc(state.city.country)} · ${esc(state.city.ko)}</b><small>${esc(state.city.name||'Chiusi')}</small></span><span class="destination-check">✓</span></button><select class="country-select" id="country-select" aria-label="국가 선택"><option value="">유럽 전체 국가</option>${europeanCountries.map(c=>`<option value="${c.code}" ${state.country===c.code?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select><div class="between" style="margin:22px 0 7px"><h3 id="search-heading" style="font-size:14px">${state.query?'검색 결과':state.country?'이 나라의 도시':'추천 여행지'}</h3><span class="small" id="search-status">검색 준비 중</span></div><div id="city-results">${cityResults()}</div></div>`)}
function cityResults(){return state.cityRows.length?state.cityRows.map((r,n)=>`<button class="city-result" data-city="${n}"><span class="country-flag" aria-hidden="true">${countryFlag(r.code)}</span><span><b>${esc(r.country||'')} · ${esc(r.ko||r.name)}</b><small>${[r.name,r.region].filter(Boolean).map(esc).join(' · ')}</small></span><span class="chevron">›</span></button>`).join(''):'<div class="empty" style="padding:35px 0">검색어를 입력하면 도시를 찾아드려요.</div>'}
let worker=new Worker('./city-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.token!==state.searchToken||state.page!=='destination')return;if(data.rows)state.cityRows=data.rows;if($('#city-results'))$('#city-results').innerHTML=cityResults();if($('#search-status'))$('#search-status').textContent=data.error?'연결을 확인해주세요':data.loading?'전체 지명 확인 중…':`${data.total??state.cityRows.length}곳`};
function startSearch(){if($('#search-heading'))$('#search-heading').textContent=state.query?'검색 결과':state.country?'이 나라의 도시':'추천 여행지';state.searchToken++;const country=europeanCountries.find(c=>c.name.includes(state.query)&&state.query.length>0);worker.postMessage({token:state.searchToken,q:country?'':state.query,code:country?.code||state.country});if($('#search-status'))$('#search-status').textContent='검색 중…'}
function ranking(){return wrap(`${top('한국인 입맛 랭킹')}<div class="scroll"><span class="eyebrow">TASTE OF ${esc(state.city.name||state.city.ko).toUpperCase()}</span><h2 style="margin:7px 0 10px">${esc(state.city.ko)}에서 찾은<br>우리 입맛에 맞는 한 끼</h2><p class="small" style="margin-bottom:23px">여행자들의 맛 기록과 내 취향을 함께 반영했어요.</p>${ranked().map((i,n)=>`<button class="rank-list" style="width:100%;text-align:left" ${i.regional?`data-rank="${i.id}"`:`data-detail="${i.id}"`}><em>${n+1}</em>${i.regional?`<div class="rank-illustration">${i.emoji||'🍽'}</div>`:`<img src="${photo(i)}" alt="${esc(foodName(i))}">`}<span><h3>${esc(foodName(i))}</h3>${ratingLine(i)}${rankingQuote(i)}<small class="rank-restaurant">${i.regional?esc(state.city.country)+'의 대표 음식':'Osteria La Solita Zuppa'}</small></span></button>`).join('')}<p class="subtle-note">별점과 한 줄 평은 디자인 확인을 위한 시연 데이터예요. 내 평가는 5·3·1점으로 환산되어 이 기기의 평균 점수에 반영돼요.</p></div>`)}
function render(){const views={home,camera,photos,analysis,restaurant:()=>mapBase('restaurant'),nearby:()=>mapBase('nearby'),asian:()=>mapBase('asian'),menu,detail,cart,order,enlarged,conversation,receipt,history:historyPage,review,friends,my,settings,destination,ranking};$('#app').innerHTML=(views[state.page]||home)();document.title=(state.page==='home'?'한입 — 유럽 미식 가이드':'한입 · '+({menu:'메뉴판',cart:'장바구니',conversation:'마주보기 대화',destination:'여행지 검색'}[state.page]||'유럽 미식 여행'));$('.device').classList.toggle('camera-mode',state.page==='camera');$('.device').classList.toggle('large-type',state.settings.font==='large');document.documentElement.style.setProperty('--user-font-scale',state.settings.font==='large'?'1.1':'1');if(state.page==='settings'&&state.settings.font==='large')$('#app').style.fontSize='15px';else $('#app').style.fontSize=''}
function modal(content){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="닫기">${icon('close')}</button>${content}</section></div>`}
function speak(text,lang='it-IT'){if(!('speechSynthesis'in window)){toast('이 기기에서는 음성 재생을 지원하지 않아요');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.85;speechSynthesis.speak(u);toast('음성을 재생하고 있어요')}
function finishOrder(){state.extra=state.tip?Math.round(sum()*state.tipPercent)/100:0;state.lastOrder={cart:state.cart.map(r=>({...r})),total:total()};save('lastOrder',state.lastOrder);go('receipt')}
function tasteModal(){modal(`<h2>내 입맛을 알려주세요</h2><label class="field-label">알레르기 <small>쉼표로 구분</small></label><input class="input" id="taste-allergy" value="${esc(state.allergies.join(', '))}" placeholder="예: 새우, 견과류"><label class="field-label">못 먹는 음식</label><input class="input" id="taste-avoid" value="${esc(state.avoid.join(', '))}"><label class="field-label">좋아하는 맛</label><input class="input" id="taste-prefs" value="${esc(state.prefs.join(', '))}"><div style="height:22px"></div>${btn('입맛 저장하기','data-action="save-taste"')}`)}
function invite(){modal(`<h2>맛있는 여행, 함께해요</h2><p class="muted">친구에게 초대 코드를 공유해보세요.<br>같은 메뉴판과 장바구니를 함께 볼 수 있어요.</p><div class="preview" style="text-align:center;font-size:30px;letter-spacing:6px;margin:25px 0">HANIP26</div>${btn('초대 코드 복사','data-action="copy-invite"')}<p class="subtle-note" style="text-align:center">프로토타입에서는 동반인 추가로 연결을 시연해요.</p>`)}
document.body.append($('#toast'));$('.device').append($('#overlay'));
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-detail],[data-enlarge-photo]');if(!el)return;if(el.dataset.add){add(el.dataset.add);render();return}if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.rank){const i=ranked().find(i=>i.id===el.dataset.rank);if(i)modal(`<span class="eyebrow">${esc(state.city.country)} · ${esc(state.city.ko)}</span><h2>${esc(i.korean)}</h2><p class="original">${esc(i.original)}</p><div class="ai-box"><span class="label">한국 음식으로 치면</span><p>${esc(i.analogy)}</p></div><div class="preview">${esc(i.description)}</div><p class="subtle-note">지역 대표 음식으로 구성한 시연용 랭킹이에요.</p>${btn('주변 식당 찾아보기',goAttr('nearby'),'secondary')}`);return}if(el.dataset.detail){state.selected=el.dataset.detail;go('detail');return}if(el.dataset.category){state.category=el.dataset.category;render();return}if(el.dataset.nearCategory){state.nearCategory=el.dataset.nearCategory;render();return}if(el.dataset.city){chooseCity(Number(el.dataset.city));return}if(el.hasAttribute('data-city')){chooseCity(0);return}if(el.dataset.qty){change(el.dataset.qty,el.dataset.owner,Number(el.dataset.delta));return}if(el.dataset.remove){state.cart=state.cart.filter(r=>!(r.id===el.dataset.remove&&r.owner===el.dataset.owner));save('cart',state.cart);render();return}if(el.hasAttribute('data-delete-photo')){state.photos.splice(Number(el.dataset.deletePhoto),1);render();return}if(el.hasAttribute('data-enlarge-photo')){let p=state.photos[Number(el.dataset.enlargePhoto)];modal(`<h2>촬영한 메뉴판</h2>${p?`<img src="${p}" alt="확대한 메뉴판" style="width:100%;border-radius:14px">`:'<div class="preview" style="font-size:22px;line-height:2"><b>Osteria La Solita Zuppa</b><br>— ZUPPE —<br>Zuppa di ceci e porcini<br>Zuppa di melanzane fumé<br>Zuppa di porri e patate<br>Zuppa di zucca e farro</div>'}<br>${btn('다시 촬영하기','data-go="camera"','secondary')}`);return}if(el.dataset.fоod)return;if(el.dataset.rating!==undefined){state.ratings[el.dataset.item]=Number(el.dataset.rating);save('ratings',state.ratings);render();later(()=>{state.review++;render()},450);return}if(el.dataset.friendAdd){state.friends.push(el.dataset.friendAdd);save('friends',state.friends);toast('여행 동반인으로 연결했어요');render();return}if(el.dataset.friendRemove){state.friends=state.friends.filter(n=>n!==el.dataset.friendRemove);save('friends',state.friends);render();return}if(el.dataset.editFriend){modal(`<h2>${esc(el.dataset.editFriend)}님 정보</h2><label class="field-label">알레르기·못 먹는 음식</label><input class="input" id="friend-note" value="${esc(friendDescription(el.dataset.editFriend))}"><div style="height:20px"></div>${btn('저장하기',`data-save-friend="${esc(el.dataset.editFriend)}"`)}`);return}if(el.dataset.saveFriend){state.friendNotes??={};state.friendNotes[el.dataset.saveFriend]=$('#friend-note').value;save('friendNotes',state.friendNotes);$('#overlay').innerHTML='';render();return}if(el.dataset.restaurant){modal(`<h2>${esc(el.dataset.restaurant)}</h2><p class="muted">이 식당을 선택할까요?</p><p class="subtle-note">디자인 시연에서는 지정한 Osteria La Solita Zuppa 메뉴판으로 연결돼요.</p>${btn('이 식당의 메뉴 보기',goAttr('menu'))}`);return}if(el.dataset.help){showHelp(el.dataset.help);return}const action=el.dataset.action;if(!action)return;switch(action){case'capture':state.photos.push(null);render();toast(`${state.photos.length}장 촬영했어요`);break;case'album':{let input=document.createElement('input');input.type='file';input.accept='image/*';input.multiple=true;input.onchange=async()=>{for(let f of input.files){if(f.size>12e6){toast('12MB 이하 이미지를 선택해주세요');continue}let url=await new Promise(resolve=>{let fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.readAsDataURL(f)});state.photos.push(url)}render()};input.click();break}case'flash':el.classList.toggle('active');el.style.background=el.classList.contains('active')?'#ffffff75':'#ffffff26';toast(el.classList.contains('active')?'플래시 켜짐':'플래시 꺼짐');break;case'sheet':$('.map-sheet').classList.toggle('expanded');break;case'map-select':modal(`<h2>지도에서 식당 선택</h2><p class="muted">지도를 움직인 뒤 아래 식당을 선택해주세요.</p><div class="restaurant-row"><div><h3>Osteria La Solita Zuppa</h3><small>토스카나 요리 · 오스테리아</small></div><button class="pill active" data-go="menu">선택</button></div>`);break;case'close-modal':$('#overlay').innerHTML='';break;case'invite':invite();break;case'copy-invite':navigator.clipboard?.writeText('HANIP26').then(()=>toast('초대 코드를 복사했어요')).catch(()=>toast('초대 코드: HANIP26'));break;case'menu-more':modal(`<h2>이 메뉴판에 대해</h2><p>Osteria La Solita Zuppa</p><p class="subtle-note">식당 공식 웹메뉴 보관 자료 · 2026.10.10<br>수프 4개 · 메인 요리 12개 · 칵테일 6개<br>시연 환율 €1 = ${rate}원</p>${btn('동반인 메뉴 담기 시연','data-action="simulate-companion"','secondary')}`);break;case'simulate-companion':add(items[3].id,state.friends[0]||'김미영',false);$('#overlay').innerHTML='';render();toast('김미영님이 담았어요',items[3]);break;case'allergen-phrase':modal(`<h2>직원에게 확인해주세요</h2><div class="preview"><p>이 음식에 ${esc([...state.avoid,...state.allergies].join(', ')||'알레르기 유발 재료')}가 들어가나요?</p><p>Mi può dire se questo piatto contiene funghi o melanzane?</p></div><br>${btn(icon('sound')+' 현지어 듣기','data-action="speak-allergen"')}`);break;case'speak-allergen':speak('Mi può dire se questo piatto contiene funghi o melanzane?');break;case'speak-order':speak(orderSentences().it);break;case'speak-staff':speak(state.conversationPhase===1?orderSentences().it:'Certamente, va bene.');break;case'speak-korean':speak('네, 알겠습니다.','ko-KR');break;case'show-order':$('#overlay').innerHTML='';state.conversationPhase=1;render();later(()=>{state.conversationPhase=2;render()},5000);break;case'skip-order':$('#overlay').innerHTML='';state.conversationPhase=2;render();break;case'my-speak':state.conversationPhase=3;render();later(()=>{state.conversationPhase=2;render()},2500);break;case'staff-speak':state.conversationPhase=2;render();break;case'finish-order':finishOrder();break;case'edit-profile':modal(`<h2>프로필 수정</h2><label class="field-label">이름</label><input class="input" id="profile-name" value="${esc(state.name)}" maxlength="20"><div style="height:22px"></div>${btn('저장하기','data-action="save-profile"')}`);break;case'save-profile':state.name=$('#profile-name').value.trim()||state.name;save('name',state.name);$('#overlay').innerHTML='';render();toast('프로필을 저장했어요');break;case'taste':tasteModal();break;case'save-taste':{const parse=s=>s.split(/[,，]/).map(s=>s.trim()).filter(Boolean);state.avoid=parse($('#taste-avoid').value);state.allergies=parse($('#taste-allergy').value);state.prefs=parse($('#taste-prefs').value);['avoid','allergies','prefs'].forEach(k=>save(k,state[k]));$('#overlay').innerHTML='';render();toast('내 입맛을 저장했어요');break}case'new-friend':modal(`<h2>새 친구 등록</h2><label class="field-label">이름</label><input class="input" id="new-friend" placeholder="친구 이름" maxlength="20"><div style="height:22px"></div>${btn('동반인으로 추가','data-action="save-new-friend"')}`);break;case'save-new-friend':{let n=$('#new-friend').value.trim();if(!n){toast('이름을 입력해주세요');break}if(!state.friends.includes(n))state.friends.push(n);save('friends',state.friends);$('#overlay').innerHTML='';render();break}case'clear-search':state.query='';$('#city-query').value='';startSearch();break;case'old-order':modal(`<h2>Trattoria Da Rosa</h2><p class="muted">피렌체 · 2026.10.24 · 2명</p><div class="preview" style="margin:20px 0">소고기 요리 2개<br>음식 및 확인한 추가 요금 <b>€ 38.50</b></div>${btn('닫기','data-action="close-modal"','secondary')}`);break}});
function chooseCity(n){let r=state.cityRows[n];if(!r)return;state.pendingCity=r;modal(`<span class="eyebrow">YOUR NEXT DESTINATION</span><h2>${esc(r.country)} · ${esc(r.ko||r.name)}</h2><p class="muted">${esc(r.name)} · ${esc(r.region||'')}</p><p class="subtle-note">여행지와 지역별 추천 기준을 이 도시로 변경할까요?</p>${btn('이 도시로 여행하기','data-action="confirm-city"')}`)}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-city"]')){state.city=state.pendingCity;save('city',state.city);go('home');toast('여행지를 변경했어요')}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='city-query'){state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(startSearch,250)}if(e.target.id==='request'){state.request=e.target.value;const s=orderSentences();$('#order-ko').textContent=s.ko;$('#order-it').textContent=s.it;$('#request-status').textContent=state.request&&!requestTranslation(state.request)?'이 요청은 시연 번역 범위 밖이에요. 치즈 제외·재료 추가·맵기·물 요청을 입력해보세요.':'자연스러운 이탈리아어 표현으로 주문 문장에 반영했어요.'}if(e.target.id==='extra'){state.extra=Math.max(0,Math.min(10000,Number(e.target.value)||0));let base=(state.lastOrder?.cart||state.cart).reduce((s,r)=>s+find(r.id).price*r.qty,0);$('#extra-amount').textContent=money(state.extra);$('#receipt-total').textContent=money(base+state.extra);$('#receipt-won').textContent=won(base+state.extra)}});
document.addEventListener('change',e=>{if(e.target.id==='country-select'){state.country=e.target.value;startSearch()}if(e.target.id==='tip'){state.tip=e.target.checked;render()}if(e.target.id==='tip-percent'){state.tipPercent=Number(e.target.value);render()}if(e.target.dataset.setting){state.settings[e.target.dataset.setting]=e.target.checked;save('settings',state.settings);toast('설정을 저장했어요')}if(e.target.id==='font-size'){state.settings.font=e.target.value;save('settings',state.settings);$('.device').style.setProperty('--font-large',e.target.value==='large'?'1':'0');toast(e.target.value==='large'?'큰 글자 모드를 적용했어요':'기본 글자 크기로 변경했어요');render()}if(e.target.id==='language'){state.settings.language=e.target.value;save('settings',state.settings);toast('표시 언어 설정을 저장했어요 · 화면은 한국어 시연이에요')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#overlay').innerHTML='';if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();e.target.click()}});
function showHelp(t){modal(`<h2>${t}</h2>${t==='사용 안내'?'<p>메뉴판 찍기 → 사진 확인 → 해석 → 식당 선택 → 메뉴 고르기 → 장바구니 → 주문 문장 → 마주보기 대화 → 영수증 순서로 둘러보세요.</p><p class="subtle-note">사진은 시연 메뉴판으로 촬영하거나 앨범에서 추가할 수 있어요. 동반인 담기 알림은 메뉴판 진입 후 한 번 자동으로 재생돼요.</p>':t==='개인정보 및 저장'?'<p>도시·입맛 설정·장바구니·평가 기록은 현재 브라우저에 저장돼요. 촬영 사진은 화면을 닫으면 사라지며 서버로 업로드하지 않아요.</p><p class="subtle-note">동반인 연결·음성 인식·OCR·실시간 환율은 시연입니다. 도시 검색은 실제 지명 데이터에서 수행해요.</p>':'<p>한입 · 유럽 미식 가이드</p><p class="subtle-note">Galaxy S26 비율의 디자인 프로토타입<br>메뉴 출처: Osteria La Solita Zuppa 공식 웹메뉴, 2026.10.10 보관 자료<br>식당 대표 사진: <a href="https://maps.app.goo.gl/L96ZagCk13Fdoeoy5" target="_blank" rel="noopener">Osteria La Solita Zuppa · Google Maps 소유자 제공</a><br>도시 데이터: <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a><br>한국어 별칭 및 근사 발음 표기를 포함해 가공했어요.</p>'}<br>${btn('확인','data-action="close-modal"','secondary')}`)}
try{items=koreanDiningPayload(await fetch('menu.json').then(r=>r.json())).map(i=>({...i,category:i.category.toLowerCase()}));state.cart=state.cart.filter(r=>find(r.id));state.lastOrder=read('lastOrder',{cart:[{id:items[2].id,owner:'나',qty:1},{id:items[3].id,owner:'김미영',qty:1},{id:items[7].id,owner:'김미영',qty:1}],total:35});state.friendNotes=read('friendNotes',{});window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(p&&p!==state.page)go(p)});const requested=location.hash.slice(1);go(['home','camera','menu','history','my','friends','destination','ranking'].includes(requested)?requested:'home')}catch(e){$('#app').innerHTML='<div class="empty">메뉴 자료를 불러오지 못했어요.<br>페이지를 새로고침해주세요.</div>';console.error(e)}

let dragState;document.addEventListener('pointerdown',e=>{if(!e.target.closest('.handle'))return;const sheet=$('.map-sheet');dragState={sheet,start:e.clientY,top:sheet.offsetTop};e.target.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(!dragState)return;const ratio=$('.device').getBoundingClientRect().height/$('.device').offsetHeight;const top=Math.max(65,Math.min(400,dragState.top+(e.clientY-dragState.start)/ratio));dragState.sheet.style.top=top+'px'});document.addEventListener('pointerup',()=>{dragState=null});
